    let operators = ['+', '-'];
    
    for &op1 in &operators {
        for &op2 in &operators {
            for &op3 in &operators {
                // Evaluate the expression based on the current combination of operators
                let result = match (op1, op2, op3) {
                    ('+', '+', '+') => digits[0] + digits[1] + digits[2] + digits[3],
                    ('+', '+', '-') => digits[0] + digits[1] + digits[2] - digits[3],
                    ('+', '-', '+') => digits[0] + digits[1] - digits[2] + digits[3],
                    ('+', '-', '-') => digits[0] + digits[1] - digits[2] - digits[3],
                    ('-', '+', '+') => digits[0] - digits[1] + digits[2] + digits[3],
                    ('-', '+', '-') => digits[0] - digits[1] + digits[2] - digits[3],
                    ('-', '-', '+') => digits[0] - digits[1] - digits[2] + digits[3],
                    ('-', '-', '-') => digits[0] - digits[1] - digits[2] - digits[3],
                };

                if result == 7 {
                    // Construct the output
                    let mut output = Vec::new();
                    output.extend_from_slice(&input[0..4]); // Add digits
                    output.push(op1); // Add first operator
                    output.push(op2); // Add second operator
                    output.push(op3); // Add third operator
                    output.push('='); // Add equals sign
                    output.push('7'); // Add the result
                    output.push('\n'); // Add newline
                    return output;
                }
            }
        }
    }
    
    // If no valid expression is found, return an empty vector (though the problem guarantees a solution)
